mapper.select:
SELECT COALESCE(SUM(latest.total_asset), 0)
FROM (
    SELECT asn.account_id, asn.total_asset,
           ROW_NUMBER() OVER (PARTITION BY asn.account_id ORDER BY asn.snapshot_date DESC) AS rn
    FROM asset_snapshot asn
    JOIN account_link al ON al.account_id = asn.account_id
    WHERE al.member_id = #{memberId}
      AND asn.snapshot_date <= #{date}
) latest
WHERE latest.rn = 1
